    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'ref_commerciale') THEN
        ALTER TABLE articles_catalogue ADD COLUMN ref_commerciale VARCHAR(255);
        RAISE NOTICE 'Colonne ref_commerciale ajoutee a articles_catalogue';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'ref_fabrication') THEN
        ALTER TABLE articles_catalogue ADD COLUMN ref_fabrication VARCHAR(255);
        RAISE NOTICE 'Colonne ref_fabrication ajoutee a articles_catalogue';
    END IF;
    -- Colonnes pour les relations
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'id_nombre_couleurs') THEN
        ALTER TABLE articles_catalogue ADD COLUMN id_nombre_couleurs INTEGER REFERENCES parametres_nombre_couleurs(id);
        RAISE NOTICE 'Colonne id_nombre_couleurs ajoutee a articles_catalogue';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'id_couleur') THEN
        ALTER TABLE articles_catalogue ADD COLUMN id_couleur INTEGER REFERENCES parametres_couleurs(id);
        RAISE NOTICE 'Colonne id_couleur ajoutee a articles_catalogue';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'id_personnalisation') THEN
        ALTER TABLE articles_catalogue ADD COLUMN id_personnalisation INTEGER REFERENCES parametres_personnalisations(id);
        RAISE NOTICE 'Colonne id_personnalisation ajoutee a articles_catalogue';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'qte_minimal_stock') THEN
        ALTER TABLE articles_catalogue ADD COLUMN qte_minimal_stock INTEGER DEFAULT 0;
        RAISE NOTICE 'Colonne qte_minimal_stock ajoutee a articles_catalogue';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'prix_vente') THEN
        ALTER TABLE articles_catalogue ADD COLUMN prix_vente DECIMAL(10,2);
        RAISE NOTICE 'Colonne prix_vente ajoutee a articles_catalogue';
    END IF;
    -- Colonnes pour les relations avec modèles, dimensions, finitions, tissages
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'id_modele') THEN
        ALTER TABLE articles_catalogue ADD COLUMN id_modele INTEGER REFERENCES parametres_modeles(id);
        RAISE NOTICE 'Colonne id_modele ajoutee a articles_catalogue';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'id_dimension') THEN
        ALTER TABLE articles_catalogue ADD COLUMN id_dimension INTEGER REFERENCES parametres_dimensions(id);
        RAISE NOTICE 'Colonne id_dimension ajoutee a articles_catalogue';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'id_finition') THEN
        ALTER TABLE articles_catalogue ADD COLUMN id_finition INTEGER REFERENCES parametres_finitions(id);
        RAISE NOTICE 'Colonne id_finition ajoutee a articles_catalogue';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'id_tissage') THEN
        ALTER TABLE articles_catalogue ADD COLUMN id_tissage INTEGER REFERENCES parametres_tissages(id);
        RAISE NOTICE 'Colonne id_tissage ajoutee a articles_catalogue';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'prix_revient') THEN
        ALTER TABLE articles_catalogue ADD COLUMN prix_revient DECIMAL(10,2);
        RAISE NOTICE 'Colonne prix_revient ajoutee a articles_catalogue';
    END IF;
    -- Colonne description (distincte de designation)
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'description') THEN
        ALTER TABLE articles_catalogue ADD COLUMN description TEXT;
        RAISE NOTICE 'Colonne description ajoutee a articles_catalogue';
    END IF;
    -- Colonne pour indiquer si l'article est dans le catalogue produit
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'articles_catalogue' AND column_name = 'dans_catalogue_produit') THEN
        ALTER TABLE articles_catalogue ADD COLUMN dans_catalogue_produit BOOLEAN DEFAULT false;
        RAISE NOTICE 'Colonne dans_catalogue_produit ajoutee a articles_catalogue';
    END IF;
END $$;

