    ref_commerciale, ref_fabrication, designation, description,
    code_article, id_modele, id_dimension, id_finition,
    id_tissage, id_nombre_couleurs, id_couleur, id_personnalisation,
    prix_revient, prix_vente, qte_minimal_stock, dans_catalogue_produit, actif
)
SELECT
    'IB2020-B12-01', 'IB2020-B-12-01', 'Fouta Modèle IBIZA Couleur Bleu Delave', 'Fouta Modèle IBIZA Couleur Bleu Delave',
    'IB2020-B12-01' as code_article,
    pm.id as id_modele,
    pd.id as id_dimension,
    pf.id as id_finition,
    t.id as id_tissage,
    pnp.id as id_nombre_couleurs,
    pc.id as id_couleur,
    pp.id as id_personnalisation,
    12.0,
    15.600000000000001,
    30,
    true,
    true
FROM parametres_modeles pm
LEFT JOIN parametres_dimensions pd ON pd.code = '2020'
LEFT JOIN parametres_finitions pf ON pf.code = 'FR'
LEFT JOIN parametres_tissages t ON t.code = 'Tissage Plat' OR t.libelle ILIKE '%Tissage Plat%'
LEFT JOIN parametres_nombre_couleurs pnp ON pnp.code = 'B'
LEFT JOIN parametres_couleurs pc ON pc.code_commercial = 'B12-01'
LEFT JOIN parametres_personnalisations pp ON pp.code = 'Oui' OR pp.libelle ILIKE '%Oui%'
WHERE pm.code_modele = 'IB'
ON CONFLICT (code_article) DO UPDATE SET
    ref_commerciale = EXCLUDED.ref_commerciale,
    ref_fabrication = EXCLUDED.ref_fabrication,
    designation = EXCLUDED.designation,
    description = EXCLUDED.description,
    id_modele = EXCLUDED.id_modele,
    id_dimension = EXCLUDED.id_dimension,
    id_finition = EXCLUDED.id_finition,
    id_tissage = EXCLUDED.id_tissage,
    id_nombre_couleurs = EXCLUDED.id_nombre_couleurs,
    id_couleur = EXCLUDED.id_couleur,
    id_personnalisation = EXCLUDED.id_personnalisation,
    prix_revient = EXCLUDED.prix_revient,
    prix_vente = EXCLUDED.prix_vente,
    prix_unitaire_base = EXCLUDED.prix_vente,
    qte_minimal_stock = EXCLUDED.qte_minimal_stock,
    dans_catalogue_produit = EXCLUDED.dans_catalogue_produit,
    date_modification = CURRENT_TIMESTAMP;

