    ref_commerciale, ref_fabrication, designation, description,
    code_article, id_modele, id_dimension, id_finition,
    id_tissage, id_nombre_couleurs, id_couleur, id_personnalisation,
    prix_revient, prix_vente, qte_minimal_stock, dans_catalogue_produit, actif
)
SELECT
    'PONBIADU-B31-26', 'PONBIADU-B-31-26', 'Poncho Adulte Modèle BICOULEUR Couleur Saumon Rouge Ferrari', 'Poncho Adulte Modèle BICOULEUR Couleur Saumon Rouge Ferrari',
    'PONBIADU-B31-26' as code_article,
    pm.id as id_modele,
    pd.id as id_dimension,
    pf.id as id_finition,
    t.id as id_tissage,
    pnp.id as id_nombre_couleurs,
    pc.id as id_couleur,
    pp.id as id_personnalisation,
    22.0,
    28.6,
    0,
    true,
    true
FROM parametres_modeles pm
LEFT JOIN parametres_dimensions pd ON pd.code = 'ADU'
LEFT JOIN parametres_finitions pf ON pf.code = 'Cou'
LEFT JOIN parametres_tissages t ON t.code = 'Eponge' OR t.libelle ILIKE '%Eponge%'
LEFT JOIN parametres_nombre_couleurs pnp ON pnp.code = 'B'
LEFT JOIN parametres_couleurs pc ON pc.code_commercial = 'B31-26'
LEFT JOIN parametres_personnalisations pp ON pp.code = 'Non' OR pp.libelle ILIKE '%Non%'
WHERE pm.code_modele = 'PONBI'
ON CONFLICT (code_article) DO UPDATE SET
    ref_commerciale = EXCLUDED.ref_commerciale,
    ref_fabrication = EXCLUDED.ref_fabrication,
